/*
这里的代码是根据五组平行线的交点画菱形，一个交点决定一个菱形。
m,n控制数量。

根据下面的代码，
我设想一种铺满任意大平面的简漏的并行算法：
——————————
p=pixel/2.5
搜索靠近p的（范围1+菱形最大长度以内的）所有网格线交点。
将每个交点用下面的代码换成4个菱形坐标，直到某个菱形包含了这个pixel，搜索完成。
——————————
虽然理论可行，代码也简单，但计算量大。（常数次数）
如果读得懂文档原理，可以直接算。
已知屏幕坐标和方向，应该不用穷举搜索，能够直接恢复岀。
*/


#define TAU 6.28318531

float w[5];

void init() {
        w[0] = .12;
        w[1] = -.3;
        w[2] = .42;
        w[3] = .2;
        w[4] = 0. - w[0] - w[1] - w[2] - w[3];
}

// 根据 方向ind, 网格grd 偏移 w[]求交点
vec2 Intersection(ivec2 ind, ivec2 grd) {
        vec2 id = vec2(ind), os = vec2(grd);
        vec2 sn = sin(id / 5. * TAU);
        vec2 cs = cos(id / 5. * TAU);

        vec2 mn;
        mn.x = os.x - w[ind.x];
        mn.y = os.y - w[ind.y];

        vec2 fz;
        //fz.x = dot(sn.yx, vec2(-mn.x,  mn.y));
        //fz.y = dot(cs.yx, vec2( mn.x, -mn.y));
        //fz.x = dot(vec2(sn.x, -sn.y), mn.yx);
        //fz.y = dot(vec2(-cs.x, cs.y), mn.yx);
        fz = mat2(sn.x,-cs.x, -sn.y, cs.y) * mn.yx;
        return fz / sin((id.x - id.y) / 5. * TAU);
}

// Diamond vertex,  intersection of five grids
// 整数化五个方向，并叠加 (路径)
vec2 DmdVtx(vec2 ItscGrd, int ind) {
        vec2 sc, sum=vec2(0);
        float a, c, d;
        for (int i = 0; i < 5; i++) {
                a = float(i) / 5. * TAU;
                sc = vec2(cos(a), sin(a));
                d = dot(ItscGrd, sc) - dot(sc, sc) / 1e3; // 防止计算误差？
                c = ceil(d + w[i]);
                c += float(i==ind);// if (i == ind) c++; //
                sum += c * sc;
        }
        return sum;
}

float dline(vec2 a, vec2 b, vec2 p) {
        b -= a;
        p -= a;
        return length(p - b * clamp(dot(p, b) / dot(b, b), 0., 1.));
}

float drawDiamond(ivec2 id, ivec2 grd, vec2 u) {
        vec2 h, a, b, c, d;

        // 求交点 id 决定两组平行线方向，mn决定哪两条 与 w[] 决定偏移
        h = Intersection(id, grd);

        // 转成4个菱形顶点
        a = DmdVtx(h, 5);
        b = DmdVtx(h, id.x);
        d = DmdVtx(h, id.y);
        c = b - a + d; // a or c = 连线中点(b+d)*.5  (- or +) .5*边长*( 一条边的单位向量e^i(id.x/5*TAU)+另一条边e^i(id.y/5*TAU) )

        // 画线
        float dist = 1e2;
        dist = min(dist, dline(a, b, u));
        dist = min(dist, dline(c, b, u));
        dist = min(dist, dline(c, d, u));
        dist = min(dist, dline(a, d, u));

        return dist;
}

void mainImage(out vec4 O, vec2 U) {
        init();
        vec2 R = iResolution.xy,
                u = 15. * (U + U - R) / R.y;

        ivec4 idid;
        float d1, d2, d = 1e2;

        for (int n = -2; n <= 2; n++){
                for (int m = -2; m <= 2; m++) {
                        for (int i = 0; i < 5; i++) {
                                idid = (ivec4(i * 3 + 1, i * 3, i * 3, i * 3 - 2) + 15) % 5;

                                d1 = drawDiamond(idid.yx, ivec2(m, n), u);
                                d2 = drawDiamond(idid.zw, ivec2(m, n), u);
                                d = min(d, min(d1, d2));
                        }
                }
        }
        O = vec4( smoothstep(45./R.y, 0., d) );
}
